(()=>{'use strict';
const copy={
fr:{heading:'À la une — Édition du 26 octobre 2026',note:'Mise à jour éditoriale du 26 octobre 2026. Les archives conservent leur date de publication.',cards:[['BRÉSIL · RÉSULTATS','Lula remporte l’élection présidentielle','Selon le TSE, Lula obtient 51,79 % des suffrages valides contre 48,21 % pour Flávio Bolsonaro, soit plus de 4,4 millions de voix d’écart.','26 octobre 2026 · Source : Tribunal supérieur électoral','#videos'],['AGL · NOTRE COMMUNAUTÉ','Merci à nos 1 000 abonnés !','AGL Télévision franchit le cap des 1 000 abonnés sur Facebook. Merci de suivre nos reportages, nos analyses et nos vidéos.','26 octobre 2026 · Rédaction AGL','#about'],['ARCHIVES · 9 OCTOBRE 2026','Retrouvez nos précédentes éditions','Les éditions et éditoriaux précédents restent consultables avec leur date d’origine.','Archives de la rédaction','edisyon-maten-2026-10-09.html']],intro:'Notre analyse en espagnol avec Tom et Leslie.',summary:'Le débat, la réponse de Lula et les différents facteurs de sa victoire. Aucun nombre de votes n’est attribué à une seule phrase.',vnote:'Analyse AGL · Présentateurs virtuels · Images du débat : TV Globo / CNN Brasil.'},
ht:{heading:'Gwo nouvèl — Edisyon 26 oktòb 2026',note:'Mizajou redaksyon 26 oktòb 2026. Achiv yo kenbe dat piblikasyon yo.',cards:[['BREZIL · REZILTA','Lula genyen eleksyon prezidansyèl la','Dapre TSE, Lula jwenn 51,79% vòt valab yo kont 48,21% pou Flávio Bolsonaro: plis pase 4,4 milyon vòt diferans.','26 oktòb 2026 · Sous: Tribinal Siperyè Elektoral','#videos'],['AGL · KOMINOTE NOU','Mèsi pou 1 000 abonnés yo!','AGL Télévision franchi etap 1 000 abonnés sou Facebook. Mèsi paske nou suiv repòtaj, analiz ak videyo nou yo.','26 oktòb 2026 · Redaksyon AGL','#about'],['ACHIV · 9 OKTÒB 2026','Li edisyon anvan yo','Ansyen edisyon ak editoryal yo rete disponib ak dat orijinal yo.','Achiv redaksyon an','edisyon-maten-2026-10-09.html']],intro:'Analiz nou an español ak Tom ak Leslie.',summary:'Deba a, repons Lula a ak plizyè faktè ki ede l genyen. Nou pa atribye yon kantite vòt ak yon sèl fraz.',vnote:'Analiz AGL · Prezantatè vityèl · Imaj deba: TV Globo / CNN Brasil.'},
en:{heading:'Top stories — October 26, 2026 edition',note:'Editorial update: October 26, 2026. Archives retain their original publication dates.',cards:[['BRAZIL · RESULTS','Lula wins the presidential election','According to the TSE, Lula received 51.79% of valid votes against 48.21% for Flávio Bolsonaro, a margin of over 4.4 million votes.','October 26, 2026 · Source: Superior Electoral Court','#videos'],['AGL · OUR COMMUNITY','Thank you to our 1,000 followers!','AGL Télévision reaches 1,000 followers on Facebook. Thank you for following our reporting, analysis and videos.','October 26, 2026 · AGL Newsroom','#about'],['ARCHIVES · OCTOBER 9, 2026','Explore previous editions','Earlier editions and editorials remain available with their original dates.','Newsroom archives','edisyon-maten-2026-10-09.html']],intro:'Our Spanish-language analysis with Tom and Leslie.',summary:'The debate, Lula’s response and the different factors behind his victory. No vote total is attributed to a single remark.',vnote:'AGL analysis · Virtual presenters · Debate images: TV Globo / CNN Brasil.'},
es:{heading:'Portada — Edición del 26 de octubre de 2026',note:'Actualización editorial del 26 de octubre de 2026. Los archivos conservan su fecha original.',cards:[['BRASIL · RESULTADOS','Lula gana las elecciones presidenciales','Según el TSE, Lula obtuvo el 51,79% de los votos válidos frente al 48,21% de Flávio Bolsonaro: más de 4,4 millones de votos de diferencia.','26 de octubre de 2026 · Fuente: Tribunal Superior Electoral','#videos'],['AGL · NUESTRA COMUNIDAD','¡Gracias por los 1.000 seguidores!','AGL Télévision alcanza los 1.000 seguidores en Facebook. Gracias por seguir nuestros reportajes, análisis y vídeos.','26 de octubre de 2026 · Redacción AGL','#about'],['ARCHIVOS · 9 DE OCTUBRE DE 2026','Consulta las ediciones anteriores','Las ediciones y los editoriales anteriores siguen disponibles con su fecha original.','Archivos de la redacción','edisyon-maten-2026-10-09.html']],intro:'Nuestro análisis en español con Tom y Leslie.',summary:'El debate, la respuesta de Lula y los distintos factores de su victoria. No se atribuye una cantidad de votos a una sola frase.',vnote:'Análisis AGL · Presentadores virtuales · Imágenes del debate: TV Globo / CNN Brasil.'}};
function render(){const lang=document.getElementById('site-language').value;const c=copy[lang]||copy.fr;document.querySelector('.agl-top time').textContent=new Intl.DateTimeFormat({fr:'fr-FR',ht:'fr-HT',en:'en-US',es:'es-ES'}[lang]||'fr-FR',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date('2026-10-26T12:00:00Z'));document.getElementById('agl-top-title').textContent=c.heading;document.getElementById('agl-top-disclaimer').textContent=c.note;const grid=document.getElementById('agl-top-grid');grid.replaceChildren();c.cards.forEach(row=>{const a=document.createElement('a');a.className='agl-story';a.href=row[4];['div','h2','p','small'].forEach((tag,i)=>{const n=document.createElement(tag);n.textContent=row[i];if(i===0)n.className='agl-category';a.append(n)});grid.append(a)});document.getElementById('video-intro').textContent=c.intro;document.getElementById('video-summary').textContent=c.summary;document.getElementById('video-note').textContent=c.vnote;}
document.getElementById('site-language').addEventListener('change',render);render();
})();
